(function(){tinymce.create("tinymce.plugins.DVImageSelector",{init:function(e,n){return e.addCommand("dvImageUpload",function(){return e.settings.render.call(e,e)}),e.ui.registry.addButton("dv_img_selector",{tooltip:"Insert Image",onAction:function(){return e.execCommand("dvImageUpload")},icon:"image"})}}),tinymce.PluginManager.add("dv_img_selector",tinymce.plugins.DVImageSelector)}).call(this);